            <h3 className="aw-content-title">{activeMeta.label}</h3>
            <p className="aw-content-subtitle">{activeMeta.subtitle}</p>
          </div>
          {renderSection()}
        </section>
      </div>
    </div>
  );
}

export default AccountWorkspace;

