import { useEffect, useMemo, useState } from "react";
import {
  FiActivity, FiCheckCircle, FiClock, FiDatabase, FiFileText, FiCalendar,
  FiLogIn, FiLogOut, FiMessageCircle, FiPercent, FiRefreshCw, FiTag,
  FiUserCheck, FiXCircle,
} from "react-icons/fi";
import { useAuth } from "../hooks/useAuth";
import { authFetch } from "../services/apiClient";
import "../styles/MyAttendance.css";

function formatDate(dateValue) {
  if (!dateValue) return "ΓÇö";
  const date = new Date(dateValue);
  if (Number.isNaN(date.getTime())) return String(dateValue);
  return date.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
}

function formatTime(value) {
  if (!value) return "ΓÇö";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function statusClass(status) {
  const normalized = String(status || "").toLowerCase();
  if (normalized === "present") return "ma-status ma-status--present";
  if (normalized === "late") return "ma-status ma-status--late";
  if (normalized === "absent") return "ma-status ma-status--absent";
  if (normalized === "excused") return "ma-status ma-status--excused";
  return "ma-status ma-status--muted";
}

function statusIcon(status) {
  const normalized = String(status || "").toLowerCase();
  if (normalized === "present") return <FiCheckCircle />;
  if (normalized === "late") return <FiClock />;
  if (normalized === "absent") return <FiXCircle />;
  if (normalized === "excused") return <FiTag />;
  return <FiTag />;
}

function standingToneClass(tone) {
  switch (tone) {
    case "good": return "ma-standing--good";
    case "warning": return "ma-standing--warning";
    case "final-warning": return "ma-standing--final";
    case "admin-review": return "ma-standing--admin";
    default: return "ma-standing--muted";
  }
}

function rateFromSummary(summary) {
  const raw = Number(summary?.attendanceRate);
  if (Number.isNaN(raw)) return 0;
  return Math.min(100, Math.max(0, raw));
}

function rateInterpretation(rate) {
  if (rate >= 90) return { text: "Excellent attendance", tone: "excellent" };
  if (rate >= 75) return { text: "Good attendance", tone: "good" };
  return { text: "Needs improvement", tone: "low" };
}

const SKELETON_ROWS = 5;

export default function MyAttendance() {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [member, setMember] = useState(null);
  const [records, setRecords] = useState([]);
  const [summary, setSummary] = useState({ totalRecords: 0, present: 0, late: 0, absent: 0, excused: 0, attendanceRate: 0 });
  const [monthlySummary, setMonthlySummary] = useState(null);
  const [error, setError] = useState("");

  // Preserved API logic: fetches the authenticated viewer's OWN attendance.
  const loadAttendance = async (opts = {}) => {
    const aborted = opts?.aborted;
    await Promise.resolve(); // defer sync setState out of the effect body
    setLoading(true);
    setError("");
    try {
      const res = await authFetch("/attendance/me");
      const data = await res.json();
      if (!res.ok) throw new Error(data?.message || "Failed to load your attendance");
      if (aborted) return;
      setMember(data?.member || null);
      setRecords(Array.isArray(data?.records) ? data.records : []);
      setSummary(data?.summary || { totalRecords: 0, present: 0, late: 0, absent: 0, excused: 0, attendanceRate: 0 });
      setMonthlySummary(data?.monthlySummary || null);
    } catch (err) {
      if (!aborted) setError(err?.message || "Unable to load your attendance.");
    } finally {
      if (!aborted) setLoading(false);
    }
  };

  useEffect(() => {
    let cancelled = false;
    loadAttendance({ aborted: cancelled });
    return () => { cancelled = true; };
  }, []);

  const memberName = useMemo(() => {
    if (!member) return user?.full_name || "Viewer";
    return [member.firstName, member.lastName].filter(Boolean).join(" ") || user?.full_name || "Viewer";
  }, [member, user]);

  const rate = useMemo(() => rateFromSummary(summary), [summary]);
  const rateInfo = useMemo(() => rateInterpretation(rate), [rate]);
  const hasRemarks = useMemo(() => records.some((r) => Boolean(r?.remarks)), [records]);

  const stats = useMemo(
    () => [
      { key: "total", label: "Total Attendance", value: summary.totalRecords, icon: <FiDatabase />, tone: "indigo" },
      { key: "present", label: "Present", value: summary.present, icon: <FiCheckCircle />, tone: "green" },
      { key: "late", label: "Late", value: summary.late, icon: <FiClock />, tone: "amber" },
      { key: "absent", label: "Absent", value: summary.absent, icon: <FiXCircle />, tone: "red" },
      { key: "rate", label: "Attendance Rate", value: `${rate}%`, icon: <FiPercent />, tone: "violet" },
    ],
    [summary, rate]
  );

    return (
    <div className="ma-page">
      <main className="ma-main">
        <header className="ma-top">
          <h1 className="ma-title">My Attendance</h1>
          <p className="ma-subtitle">Your personal KATAGA attendance portal</p>
        </header>

        {loading ? (
          <SkeletonView />
        ) : error ? (
          <ErrorView message="Unable to load your attendance" sub="Please try again." onRetry={() => loadAttendance()} />
        ) : !member ? (
          <Card className="ma-notlinked">
            <div className="ma-notlinked-icon" aria-hidden><FiUserCheck /></div>
            <h3 className="ma-notlinked-title">Account not linked</h3>
            <p className="ma-notlinked-body">
              Your account is not yet linked to a participant record. Please contact an administrator.
            </p>
          </Card>
        ) : (
          <>
            <section className="ma-hero ma-card">
              <div className="ma-hero-glow" aria-hidden />
              <div className="ma-hero-inner">
                <div className="ma-avatar" aria-hidden><FiUserCheck /></div>
                <div className="ma-hero-text">
                  <h2 className="ma-hero-name">{memberName}</h2>
                  <p className="ma-hero-role">Viewer ┬╖ {user?.full_name || "Member"}</p>
                  <div className="ma-hero-meta">
                    <span className="ma-hero-meta-item"><FiUserCheck /> Participant {member.participantIdentifier || "ΓÇö"}</span>
                    <span className="ma-hero-meta-item"><FiActivity /> {member.department || "ΓÇö"}</span>
                    <span className="ma-hero-meta-item"><FiCalendar /> Year {member.year || "ΓÇö"}</span>
                    <span className="ma-hero-meta-item"><FiTag /> Section {member.section || "ΓÇö"}</span>
                  </div>
                </div>
              </div>
            </section>
                        <section className="ma-section">
              <h3 className="ma-section-title">Attendance Summary</h3>
              <div className="ma-stats ma-stats-grid">
                {stats.map((s) => (
                  <div key={s.key} className={`ma-stat ma-stat--${s.tone} ma-card`}>
                    <div className={`ma-stat-icon ma-stat-icon--${s.tone}`} aria-hidden>{s.icon}</div>
                    <div className="ma-stat-body">
                      <span className="ma-stat-label">{s.label}</span>
                      <span className="ma-stat-value">{s.value}</span>
                    </div>
                  </div>
                ))}
              </div>
            </section>

            <section className="ma-section">
              <div className="ma-rate ma-card">
                <div className="ma-rate-head">
                  <div className="ma-rate-icon" aria-hidden><FiPercent /></div>
                  <h3 className="ma-rate-title">Attendance Rate</h3>
                </div>
                <div className="ma-rate-main">
                  <div className="ma-rate-value">{rate}%</div>
                  <div className="ma-rate-bar">
                    <div className={`ma-rate-fill ma-rate-fill--${rateInfo.tone}`} style={{ width: `${rate}%` }} />
                  </div>
                  <div className={`ma-rate-interp ma-rate-interp--${rateInfo.tone}`}>{rateInfo.text}</div>
                </div>
              </div>
            </section>

            <section className="ma-section">
              <h3 className="ma-section-title">
                Monthly Attendance Summary ΓÇö {monthlySummary?.label || "Current Month"}
              </h3>
              {monthlySummary ? (
                <div className="ma-card" style={{ padding: "18px 20px" }}>
                  <div className="ma-stats ma-stats-grid">
                    {[
                      { key: "m-total", label: "Total Attendance", value: monthlySummary.present + monthlySummary.late + monthlySummary.absent + monthlySummary.excused, tone: "indigo" },
                      { key: "m-present", label: "Present", value: monthlySummary.present, tone: "green" },
                      { key: "m-late", label: "Late", value: monthlySummary.late, tone: "amber" },
                      { key: "m-absent", label: "Actual Absent", value: monthlySummary.absent, tone: "red" },
                      { key: "m-excused", label: "Excused", value: monthlySummary.excused, tone: "violet" },
                      { key: "m-rate", label: "Attendance Rate", value: `${monthlySummary.attendanceRate || 0}%`, tone: "indigo" },
                    ].map((s) => (
                      <div key={s.key} className={`ma-stat ma-stat--${s.tone} ma-card`}>
                        <div className="ma-stat-body">
                          <span className="ma-stat-label">{s.label}</span>
                          <span className="ma-stat-value">{s.value}</span>
                        </div>
                      </div>
                    ))}
                  </div>

                  <div className={`ma-standing ${standingToneClass(monthlySummary.standingTone)}`}>
                    <span className="ma-standing-label">Attendance Standing</span>
                    <span className="ma-standing-value">{monthlySummary.standing || "Good Standing"}</span>
                  </div>

                  {(monthlySummary.absent > 0 || monthlySummary.late > 0) && (
                    <div className="ma-breakdown">
                      <div className="ma-breakdown-row"><span>Actual Absences:</span><strong>{monthlySummary.absent}</strong></div>
                      <div className="ma-breakdown-row"><span>Late Records:</span><strong>{monthlySummary.late}</strong></div>
                      <div className="ma-breakdown-row"><span>Late Equivalent ({Math.floor(3)} lates = 1 absence):</span><strong>{monthlySummary.lateEquivalentAbsences} Absence{monthlySummary.lateEquivalentAbsences === 1 ? "" : "s"}</strong></div>
                      <div className="ma-breakdown-row"><span>Effective Absences:</span><strong>{monthlySummary.effectiveAbsences}</strong></div>
                    </div>
                  )}
                </div>
              ) : (
                <div className="ma-card" style={{ padding: "18px 20px" }}>
                  <p style={{ margin: 0, color: "var(--muted-2)" }}>
                    This month's summary starts fresh on the 1st. Previous months remain in your history below.
                  </p>
                </div>
              )}
            </section>

            <section className="ma-section">
              <h3 className="ma-section-title">My Attendance History</h3>
              {records.length === 0 ? (
                <EmptyState />
              ) : (
                <div className="ma-history ma-card">
                  <div className="ma-table-wrap">
                    <table className="ma-table">
                      <thead>
                        <tr>
                          <th>Date</th>
                          <th>Activity / Event</th>
                          <th>Time In</th>
                          <th>Time Out</th>
                          <th>Status</th>
                          {hasRemarks && <th>Remarks</th>}
                        </tr>
                      </thead>
                      <tbody>
                        {records.map((record) => (
                          <tr key={record.id}>
                            <td data-label="Date">{formatDate(record.attendanceDate)}</td>
                            <td data-label="Activity">{record.activity || "Attendance"}</td>
                            <td data-label="Time In">{formatTime(record.timeIn)}</td>
                            <td data-label="Time Out">{formatTime(record.timeOut)}</td>
                            <td data-label="Status">
                              <span className={statusClass(record.status)}>
                                <span className="ma-status-ink" aria-hidden>{statusIcon(record.status)}</span>
                                {record.status || "ΓÇö"}
                              </span>
                            </td>
                            {hasRemarks && <td data-label="Remarks">{record.remarks || "ΓÇö"}</td>}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <div className="ma-cards" role="list">
                    {records.map((record) => (
                      <div key={record.id} className="ma-record-card" role="listitem">
                        <div className="ma-record-card-head">
                          <span className="ma-record-date">{formatDate(record.attendanceDate)}</span>
                          <span className={statusClass(record.status)}>
                            <span className="ma-status-ink" aria-hidden>{statusIcon(record.status)}</span>
                            {record.status || "ΓÇö"}
                          </span>
                        </div>
                        <div className="ma-record-row"><span className="ma-record-label"><FiActivity /> Activity</span><span className="ma-record-value">{record.activity || "Attendance"}</span></div>
                        <div className="ma-record-row"><span className="ma-record-label"><FiLogIn /> Time In</span><span className="ma-record-value">{formatTime(record.timeIn)}</span></div>
                        <div className="ma-record-row"><span className="ma-record-label"><FiLogOut /> Time Out</span><span className="ma-record-value">{formatTime(record.timeOut)}</span></div>
                        {hasRemarks && record.remarks && (
                          <div className="ma-record-row"><span className="ma-record-label"><FiMessageCircle /> Remarks</span><span className="ma-record-value">{record.remarks}</span></div>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </section>

          </>
        )}
      </main>
    </div>
  );
}

function Card({ className = "", children }) {
  return <div className={`ma-card ${className}`.trim()}>{children}</div>;
}

function SkeletonView() {
  return (
    <div className="ma-skeleton">
      <div className="ma-skel-hero ma-card">
        <div className="ma-skel-avatar" />
        <div className="ma-skel-line ma-skel-line--title" />
        <div className="ma-skel-line ma-skel-line--meta" />
      </div>
      <div className="ma-stats ma-stats-grid">
        {Array.from({ length: 5 }).map((_, i) => (
          <div key={i} className="ma-skel-stat ma-card">
            <div className="ma-skel-icon" />
            <div className="ma-skel-line ma-skel-line--stat" />
            <div className="ma-skel-line ma-skel-line--stat ma-skel-line--stat2" />
          </div>
        ))}
      </div>
      <div className="ma-skel-rate ma-card">
        <div className="ma-skel-line ma-skel-line--rate" />
        <div className="ma-skel-bar" />
        <div className="ma-skel-line ma-skel-line--interp" />
      </div>
      {Array.from({ length: SKELETON_ROWS }).map((_, i) => (
        <div key={i} className="ma-skel-row ma-card" />
      ))}
    </div>
  );
}

function ErrorView({ message, sub, onRetry }) {
  return (
    <div className="ma-error ma-card">
      <div className="ma-error-icon" aria-hidden><FiFileText /></div>
      <h3 className="ma-error-title">{message}</h3>
      <p className="ma-error-sub">{sub}</p>
      <button type="button" className="ui-btn ui-btn-primary ma-error-btn" onClick={onRetry}>
        <FiRefreshCw /> Retry
      </button>
    </div>
  );
}

function EmptyState() {
  return (
    <div className="ma-empty ma-card">
      <div className="ma-empty-icon" aria-hidden><FiCalendar /></div>
      <h3 className="ma-empty-title">No attendance records yet</h3>
      <p className="ma-empty-body">
        Your attendance records will appear here once you check in to a KATAGA activity.
      </p>
    </div>
  );
}

/**
 * Organizations ΓÇö Super Admin organization & invitation code management.
 */
import { useCallback, useEffect, useState } from "react";
import {
  FaBuilding,
  FaPlus,
  FaEdit,
  FaTrash,
  FaCopy,
  FaUsers,
  FaKey,
  FaCheck,
  FaTimes,
  FaArchive,
  FaSearch,
  FaSyncAlt,
} from "react-icons/fa";
import organizationService from "../services/organizationService";
import { getRoleLabel } from "../constants/roles";
import "../styles/Organizations.css";

const EMPTY_FORM = { name: "", department: "", description: "" };

function Organizations() {
  const [organizations, setOrganizations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [toast, setToast] = useState({ kind: "", message: "", visible: false });
  const [search, setSearch] = useState("");

  // Modal state
  const [showCreate, setShowCreate] = useState(false);
  const [form, setForm] = useState({ ...EMPTY_FORM });
  const [editing, setEditing] = useState(null);
  const [saving, setSaving] = useState(false);

  // Invitation code modal
  const [showCodes, setShowCodes] = useState(null);
  const [codes, setCodes] = useState([]);
  const [codesLoading, setCodesLoading] = useState(false);
  const [newCode, setNewCode] = useState({ code: "", expires_at: "", max_uses: "" });
  const [generating, setGenerating] = useState(false);

  const showToast = useCallback((kind, message) => {
    setToast({ kind, message, visible: true });
    window.setTimeout(() => setToast((prev) => ({ ...prev, visible: false })), 2600);
  }, []);

  const loadOrganizations = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const data = await organizationService.getOrganizations();
      setOrganizations(data.organizations || []);
    } catch (err) {
      setError(err.response?.data?.message || err.message || "Failed to load organizations.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadOrganizations();
  }, [loadOrganizations]);

  const filtered = organizations.filter((o) =>
    !search ||
    (o.name || "").toLowerCase().includes(search.toLowerCase()) ||
    (o.orgCode || "").toLowerCase().includes(search.toLowerCase()) ||
    (o.department || "").toLowerCase().includes(search.toLowerCase())
  );

  const handleCreate = async (e) => {
    e.preventDefault();
    if (!form.name.trim()) {
      showToast("error", "Organization name is required.");
      return;
    }
    setSaving(true);
    try {
      if (editing) {
        await organizationService.updateOrganization(editing.id, form);
        showToast("success", "Organization updated.");
      } else {
        await organizationService.createOrganization(form);
        showToast("success", "Organization created.");
      }
      setShowCreate(false);
      setForm({ ...EMPTY_FORM });
      setEditing(null);
      await loadOrganizations();
    } catch (err) {
      showToast("error", err.response?.data?.message || err.message || "Failed to save organization.");
    } finally {
      setSaving(false);
    }
  };

  const openEdit = (org) => {
    setEditing(org);
    setForm({ name: org.name || "", department: org.department || "", description: org.description || "" });
    setShowCreate(true);
  };

  const handleArchive = async (org) => {
    if (!window.confirm(`Archive organization "${org.name}"? This can be undone by reactivating.`)) return;
    try {
      await organizationService.deleteOrganization(org.id);
      showToast("success", "Organization archived.");
      await loadOrganizations();
    } catch (err) {
      showToast("error", err.response?.data?.message || "Failed to archive organization.");
    }
  };

  const openCodes = async (org) => {
    setShowCodes(org);
    setNewCode({ code: "", expires_at: "", max_uses: "" });
    setCodesLoading(true);
    try {
      const data = await organizationService.getInvitationCodes(org.id);
      setCodes(data.codes || []);
    } catch (err) {
      setCodes([]);
      showToast("error", err.response?.data?.message || "Failed to load invitation codes.");
    } finally {
      setCodesLoading(false);
    }
  };

  const handleGenerateCode = async (e) => {
    e.preventDefault();
    if (!showCodes) return;
    setGenerating(true);
    try {
      await organizationService.createInvitationCode(showCodes.id, {
        code: newCode.code,
        expires_at: newCode.expires_at || null,
        max_uses: newCode.max_uses ? Number(newCode.max_uses) : undefined,
      });
      showToast("success", "Invitation code created.");
      setNewCode({ code: "", expires_at: "", max_uses: "" });
      const data = await organizationService.getInvitationCodes(showCodes.id);
      setCodes(data.codes || []);
    } catch (err) {
      showToast("error", err.response?.data?.message || err.message || "Failed to create invitation code.");
    } finally {
      setGenerating(false);
    }
  };

  const handleToggleCode = async (code) => {
    const next = code.status === "active" ? "disabled" : "active";
    try {
      await organizationService.updateInvitationCode(code.id, { status: next });
      setCodes((prev) => prev.map((c) => (c.id === code.id ? { ...c, status: next } : c)));
      showToast("success", `Code ${next === "active" ? "activated" : "disabled"}.`);
    } catch (err) {
      showToast("error", err.response?.data?.message || "Failed to update invitation code.");
    }
  };

  const handleDeleteCode = async (code) => {
    if (!window.confirm(`Delete invitation code "${code.code}"?`)) return;
    try {
      await organizationService.deleteInvitationCode(code.id);
      setCodes((prev) => prev.filter((c) => c.id !== code.id));
      showToast("success", "Invitation code deleted.");
    } catch (err) {
      showToast("error", err.response?.data?.message || "Failed to delete invitation code.");
    }
  };

  const copyText = async (text) => {
    try {
      await navigator.clipboard.writeText(text);
      showToast("success", "Copied to clipboard.");
    } catch {
      showToast("error", "Failed to copy.");
    }
  };

  return (
    <div className="org-page">
      {toast.visible && (
        <div className={`org-toast org-toast--${toast.kind}`}>
          {toast.kind === "success" ? <FaCheck /> : <FaTimes />}
          <span>{toast.message}</span>
        </div>
      )}

      {/* Hero */}
      <div className="org-hero">
        <div className="org-hero-icon"><FaBuilding /></div>
        <div className="org-hero-text">
          <h2>Organizations</h2>
          <p>Create, manage, and provision invitation codes for organizations.</p>
        </div>
        <button className="org-add-btn" onClick={() => { setEditing(null); setForm({ ...EMPTY_FORM }); setShowCreate(true); }}>
          <FaPlus /> New Organization
        </button>
      </div>

      {/* Toolbar */}
      <div className="org-toolbar">
        <div className="org-search">
          <FaSearch />
          <input
            type="text"
            placeholder="Search by name, code, or department..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <button className="org-refresh-btn" onClick={loadOrganizations} title="Refresh">
          <FaSyncAlt className={loading ? "org-spin" : ""} />
        </button>
      </div>

      {error && <div className="org-error">{error}</div>}

      {loading ? (
        <div className="org-loading">Loading organizations...</div>
      ) : filtered.length === 0 ? (
        <div className="org-empty">
          <FaBuilding />
          <p>No organizations found.</p>
          <span>Create your first organization to get started.</span>
        </div>
      ) : (
        <div className="org-grid">
          {filtered.map((org) => (
            <div key={org.id} className={`org-card${org.status !== "active" ? " org-card--archived" : ""}`}>
              <div className="org-card-header">
                <div className="org-card-logo">{org.name?.charAt(0)?.toUpperCase() || "O"}</div>
                <div className="org-card-title">
                  <h3>{org.name}</h3>
                  <span className="org-card-code">{org.orgCode}</span>
                </div>
                <span className={`org-status org-status--${org.status}`}>{org.status}</span>
              </div>

              <div className="org-card-body">
                {org.department && (
                  <div className="org-meta">
                    <span className="org-meta-label">Department</span>
                    <span className="org-meta-value">{org.department}</span>
                  </div>
                )}
                {org.description && (
                  <div className="org-meta">
                    <span className="org-meta-label">Description</span>
                    <span className="org-meta-value org-meta-desc">{org.description}</span>
                  </div>
                )}
                <div className="org-meta">
                  <span className="org-meta-label">Members</span>
                  <span className="org-meta-value"><FaUsers /> {org.memberCount ?? 0}</span>
                </div>
                <div className="org-meta">
                  <span className="org-meta-label">Active Codes</span>
                  <span className="org-meta-value"><FaKey /> {org.activeCodeCount ?? 0}</span>
                </div>
              </div>

              <div className="org-card-actions">
                <button onClick={() => openCodes(org)}><FaKey /> Invitation Codes</button>
                <button onClick={() => openEdit(org)}><FaEdit /> Edit</button>
                {org.status === "active" && (
                  <button className="org-btn-danger" onClick={() => handleArchive(org)}><FaArchive /> Archive</button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Create/Edit Modal */}
      {showCreate && (
        <div className="org-modal-overlay" onClick={() => !saving && setShowCreate(false)}>
          <div className="org-modal" onClick={(e) => e.stopPropagation()}>
            <div className="org-modal-header">
              <h3>{editing ? "Edit Organization" : "Create Organization"}</h3>
              <button className="org-modal-close" onClick={() => setShowCreate(false)}><FaTimes /></button>
            </div>
            <form onSubmit={handleCreate}>
              <div className="org-form-field">
                <label>Organization Name *</label>
                <input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. BSIT Department" />
              </div>
              <div className="org-form-field">
                <label>Department</label>
                <input type="text" value={form.department} onChange={(e) => setForm({ ...form, department: e.target.value })} placeholder="e.g. College of Engineering" />
              </div>
              <div className="org-form-field">
                <label>Description</label>
                <textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Brief description" rows={3} />
              </div>
              <div className="org-form-actions">
                <button type="button" className="org-btn-cancel" onClick={() => setShowCreate(false)} disabled={saving}>Cancel</button>
                <button type="submit" className="org-btn-primary" disabled={saving}>
                  {saving ? "Saving..." : (editing ? "Save Changes" : "Create Organization")}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Invitation Codes Modal */}
      {showCodes && (
        <div className="org-modal-overlay" onClick={() => setShowCodes(null)}>
          <div className="org-modal org-modal--wide" onClick={(e) => e.stopPropagation()}>
            <div className="org-modal-header">
              <h3>Invitation Codes ΓÇö {showCodes.name}</h3>
              <button className="org-modal-close" onClick={() => setShowCodes(null)}><FaTimes /></button>
            </div>

            <form onSubmit={handleGenerateCode} className="org-code-generate">
              <div className="org-form-field">
                <label>Custom Code (optional)</label>
                <input type="text" value={newCode.code} onChange={(e) => setNewCode({ ...newCode, code: e.target.value.toUpperCase() })} placeholder="e.g. BSIT-2026" />
              </div>
              <div className="org-form-field">
                <label>Expiration Date (optional)</label>
                <input type="date" value={newCode.expires_at} onChange={(e) => setNewCode({ ...newCode, expires_at: e.target.value })} />
              </div>
              <div className="org-form-field">
                <label>Max Uses (optional)</label>
                <input type="number" min="1" value={newCode.max_uses} onChange={(e) => setNewCode({ ...newCode, max_uses: e.target.value })} placeholder="Unlimited" />
              </div>
              <button type="submit" className="org-btn-primary" disabled={generating}>
                {generating ? "Generating..." : "Generate Code"}
              </button>
            </form>

            <div className="org-codes-list">
              {codesLoading ? (
                <div className="org-loading">Loading codes...</div>
              ) : codes.length === 0 ? (
                <div className="org-empty org-empty--small">
                  <FaKey />
                  <p>No invitation codes yet.</p>
                </div>
              ) : (
                codes.map((code) => (
                  <div key={code.id} className={`org-code-row${code.status !== "active" ? " org-code-row--disabled" : ""}`}>
                    <div className="org-code-info">
                      <div className="org-code-value">
                        <code>{code.code}</code>
                        <button className="org-copy-btn" onClick={() => copyText(code.code)} title="Copy"><FaCopy /></button>
                      </div>
                      <div className="org-code-details">
                        {code.expiresAt && <span>Expires: {new Date(code.expiresAt).toLocaleDateString()}</span>}
                        {code.maxUses > 0 && <span>Uses: {code.usedCount}/{code.maxUses}</span>}
                        {!code.expiresAt && code.maxUses === 0 && <span>Unlimited</span>}
                      </div>
                    </div>
                    <div className="org-code-actions">
                      <span className={`org-status org-status--${code.status}`}>{code.status}</span>
                      <button className="org-btn-toggle" onClick={() => handleToggleCode(code)}>
                        {code.status === "active" ? "Disable" : "Enable"}
                      </button>
                      <button className="org-btn-danger" onClick={() => handleDeleteCode(code)}><FaTrash /></button>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default Organizations;

